  meals: ['meal', 'meal', 'Upcoming meals', 'Your planned cooking nights', 1],
  shopping: ['cart', 'shop', 'Shopping list', 'Things still to get, with a tick button', 1],
  summary: ['shield', 'car', 'Overdue, due soon, all good', 'The three counters', 1],
