const waterPill = lab => `<span class="pill waterlater">💧 ${esc(lab)}</span>`;
const todoDuePill = (t, d) => { if (todoStatus(t) === 'doing') return progPill(); const b = waterBlock(t); return b ? waterPill(b) : pill(d == null ? daysLeft(t.due) : d); };
