const TEXT_SIZES = [['sm', 'Small', 'text-sm'], ['md', 'Normal', ''], ['lg', 'Large', 'text-lg'], ['xl', 'Extra large', 'text-xl'], ['xxl', 'Huge', 'text-xxl']];
