  const day = gymDayNow(), list = mine.filter(m => m.day === 'W' || m.day === day);
  const today = todayISO(), doneToday = new Set(g.log.filter(x => x.d === today).map(x => x.id));
  const month = today.slice(0, 7), sessions = new Set(g.log.filter(x => String(x.d || '').startsWith(month)).map(x => x.d)).size;
  const intro = `<div class="s" style="margin:2px 4px 8px">Built from the machines you've ticked as “I use this”. Cardio is the warm-up, then Day A or Day B.</div>`;
  const toggle = `<div class="chips">${[['A', 'Day A · push and legs'], ['B', 'Day B · pull and core']].map(x => `<button class="chip ${x[0] === day ? 'on' : ''}" onclick="gymDay=${jsArg(x[0])};document.getElementById('gymlist').innerHTML=gymProgram()">${x[1]}</button>`).join('')}</div>`;
