    const week = days.map(d => `<i title="${esc(fmtW(d))}" style="display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:3px;background:${medTakenAt(x.id, d) ? 'var(--ok,#2e7d32)' : '#8884'}"></i>`).join('');
