function musPicks() {
  const wk = Math.floor(todayT() / (7 * DAY)), a = MUS_POOL.slice();
  let seed = wk * 9301 + 49297; const rnd = () => (seed = (seed * 9301 + 49297) % 233280) / 233280;
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a.slice(0, 15);
}
