/* ================= 2.26.6: Notifications page sections =================
   Urgent: weather and road warnings, overdue and due today. Coming up: tomorrow and the next days (cars within 7).
   From Sarah: things she added in the last 24 hours. Flagged events last. Everything counts in the bell.
   Uses Coming up (so nag items and the garden rule are already filtered); Busy calendar entries and sport are left out. */
function glDueItems() {
  const out = [];
  try { glDueItems.nl = new Set(nlItems().map(x => x.id)); } catch (e) { glDueItems.nl = null; }
  try {
    glCU().forEach(x => {
      const k = x.kind, d = x.days, name = String(x.name || x.html || '').replace(/<[^>]+>/g, ' ');
      if (!glOk(name) || /\bbusy\b/i.test(name)) return;
      const t = x.ref && x.ref.todo, hi = !!(t && t.priority === 'high');
      if (k === 'todo') return; // 2.26.34: to-dos are added below (one card each)
      if (k === 'car' && x.ref && carProg(x.ref.car, x.ref.part)) { // 2.26.48: in progress → In progress section; WOF recheck within 7 days → Coming up, overdue → Urgent
        const cp = carProgCards().find(y => y.car.id === x.ref.car.id && y.part === x.ref.part);
        if (cp && cp.rd != null && cp.rd <= 7) out.push({ days: cp.rd, html: cp.html, noCount: cp.rd > 1 });
        return;
      }
      const ok = k === 'bill' || k === 'pay' || k === 'loan' ? d <= 1 : k === 'car' || k === 'driver' ? d <= 7 : k === 'bday' ? false : ['appt', 'ext', 'health', 'custom', 'mine'].includes(k) ? d >= 0 && d <= 1 : k === 'todo' ? d < 0 || (hi && d <= 1) : k === 'comm' || k === 'claim' ? d <= 7 : false; // 2.26.6: commission and claim reminders (read from the app only)
      if (!ok) return;
      let h = ''; try { h = cuRowHtml(x); } catch (e) { return; }
      out.push({ days: d, html: h });
    });
  } catch (e) { }
  // 2.26.34: every open dated to-do: overdue/today → Urgent, 1–7 days → Coming up. Only overdue, today and tomorrow count.
  // In-progress ones that aren't overdue/today go to the In progress section instead; new ones stay under 'New on your lists'.
  try {
    (S.todos || []).forEach(t => {
      if (!t || t.done || !t.due || !t.title || !glOk(t.title) || (glDueItems.nl && glDueItems.nl.has(t.id))) return;
      const d = daysLeft(t.due); if (d > 7) return;
      const doing = todoStatus(t) === 'doing'; if (doing) return; // 2.26.48: in progress stays in the In progress section
      if (waterBlock(t)) { out.push({ days: 0.5, html: glTodoCard(t, d), noCount: true, todoId: t.id }); return; } // blocked by the garden rule: Coming up, not counted
      out.push({ days: d, html: glTodoCard(t, d), noCount: d > 1, todoId: t.id });
    });
  } catch (e) { }
  // 2.26.60: ASB card due in 3 days or less, until it's paid in full (one gentle row, no push)
  try { const g = !cardDays().dueGuess && cardGoal(); if (g && !g.full) { const d = daysLeft(g.due); if (d >= 0 && d <= 3) out.push({ days: Math.max(1, d), noCount: true, html: `<button class="row" onclick="go('#cashflow')"><div class="ic bill">💳</div><div class="tx"><div class="t">ASB credit card due ${d === 0 ? 'today' : d === 1 ? 'tomorrow' : fmtW(g.due)}</div><div class="s">${g.paid ? 'Part paid ' + money(g.paid) + ' · ' : ''}${money(g.left)} to pay it off in full</div></div><span class="pill">${d === 0 ? 'Today' : d + (d === 1 ? ' day' : ' days')}</span></button>` }); } } catch (e) { }
  // 2.26.31: birthdays from the Birthdays list, 28 days ahead. Today → Urgent; 1–28 days → Coming up; only 0–7 days count toward the bell badge.
  try {
    (S.birthdays || []).map(b => Object.assign({ b }, bdayInfo(b))).filter(x => x.d >= 0 && x.d <= 28 && glOk(x.b.name)).forEach(x => {
      const when = x.d === 0 ? 'Today 🎂' : x.d === 1 ? 'Tomorrow' : x.d + ' days to go';
      const h = `<button class="row" onclick="go('#birthdays')"><div class="ic bday">${I('cake')}</div><div class="tx"><div class="t">${esc(x.b.name)}’s birthday</div><div class="s">${fmtW(x.iso)}${x.age > 0 ? ` · turns ${x.age}` : ''}</div></div><span class="pill">${when}</span></button>`;
      out.push({ days: x.d, html: h, noCount: x.d > 7 });
    });
  } catch (e) { }
  return out;
}
// 2.26.32: anything newly added to any of Shane's lists (to-do lists incl. custom ones, shopping) is a priority on Notifications
