  return (await r.json()).map(x => ({ lat: +x.lat, lon: +x.lon, label: String(x.display_name || '').split(',').slice(0, 4).join(',') })).filter(x => validLL(x.lat, x.lon)).filter((x, i, a) => a.findIndex(y => y.label === x.label) === i);
